<?php
declare(strict_types=1);
require_once __DIR__.'/../includes/auth.php';require_once __DIR__.'/../includes/layout.php';require_once __DIR__.'/../includes/geop_v8.php';require_once __DIR__.'/../includes/gestao_integrada.php';
require_login();check_csrf();geop_v8_boot($pdo);
if (!geop_v8_feature_ready($pdo)) {
    if ((current_user()['perfil'] ?? '') === 'TI') redirect('atualizar_geop_v8');
    http_response_code(503); die('O módulo GEOP V8 aguarda a atualização do banco pelo TI.');
}$u=current_user();$uid=(int)$u['id'];$perfil=strtoupper((string)$u['perfil']);$canManage=in_array($perfil,['TI','GESTOR','GESTOR_SINDICO','COORDENADOR_OPERACOES_OBRAS'],true);$msg='';$err='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 try{$action=$_POST['action']??'';
  if($action==='criar'){
   $osId=(int)($_POST['ordem_servico_id']??0);$just=trim((string)($_POST['justificativa']??''));$desc=trim((string)($_POST['descricao_item']??''));$q=(float)str_replace(',','.',(string)($_POST['quantidade']??'1'));$unit=trim((string)($_POST['unidade']??''));$price=(float)str_replace(',','.',(string)($_POST['custo_unitario']??'0'));$materialId=(int)($_POST['material_id']??0);if($desc===''||$q<=0)throw new RuntimeException('Informe item e quantidade.');$total=$q*$price;$pdo->beginTransaction();$pdo->prepare("INSERT INTO compras_solicitacoes(ordem_servico_id,solicitante_id,status,justificativa,valor_previsto,solicitado_em) VALUES(?,?,'PENDENTE',?,?,NOW())")->execute([$osId?:null,$uid,$just,$total]);$cid=(int)$pdo->lastInsertId();$pdo->prepare("INSERT INTO compras_itens(compra_id,material_id,descricao,quantidade,unidade,custo_unitario_previsto) VALUES(?,?,?,?,?,?)")->execute([$cid,$materialId?:null,$desc,$q,$unit?:null,$price]);$pdo->prepare("INSERT INTO aprovacoes(tipo,entidade,entidade_id,solicitante_id,status,observacao) VALUES('COMPRA','compra_solicitacao',?,?,'PENDENTE',?)")->execute([$cid,$uid,$just]);$pdo->commit();if(function_exists('gestao_usuarios_gestao'))foreach(gestao_usuarios_gestao($pdo) as $gid)if($gid!==$uid)gestao_notificar($pdo,$gid,'COMPRA_APROVACAO','Compra aguardando aprovação','Solicitação #'.$cid.' — R$ '.number_format($total,2,',','.'),app_path('central_aprovacoes'),'compra-'.$cid.'-'.$gid);$msg='Solicitação de compra criada e enviada para aprovação.';
  }elseif($action==='marcar_comprada'&&$canManage){$id=(int)$_POST['id'];$forn=trim((string)($_POST['fornecedor']??''));$doc=trim((string)($_POST['documento']??''));$valor=(float)str_replace(',','.',(string)($_POST['valor_final']??'0'));$pdo->prepare("UPDATE compras_solicitacoes SET status='COMPRADA',fornecedor=?,numero_documento=?,valor_final=?,comprado_em=NOW() WHERE id=? AND status='APROVADA'")->execute([$forn?:null,$doc?:null,$valor,$id]);$msg='Compra marcada como realizada.';
  }elseif($action==='receber'&&$canManage){$id=(int)$_POST['id'];$pdo->beginTransaction();$st=$pdo->prepare("SELECT * FROM compras_itens WHERE compra_id=?");$st->execute([$id]);foreach($st->fetchAll(PDO::FETCH_ASSOC) as $it){if(!empty($it['material_id'])){$cost=$it['custo_unitario_final']!==null?$it['custo_unitario_final']:$it['custo_unitario_previsto'];$pdo->prepare("UPDATE estoque_materiais SET quantidade_atual=quantidade_atual+?,custo_unitario=CASE WHEN ?>0 THEN ? ELSE custo_unitario END,atualizado_em=NOW() WHERE id=?")->execute([$it['quantidade'],$cost,$cost,$it['material_id']]);$pdo->prepare("INSERT INTO movimentacoes_estoque(material_id,ordem_servico_id,usuario_id,tipo,quantidade,custo_unitario,observacao) SELECT ?,ordem_servico_id,?,'ENTRADA_COMPRA',?,?,? FROM compras_solicitacoes WHERE id=?")->execute([$it['material_id'],$uid,$it['quantidade'],$cost,'Recebimento compra #'.$id,$id]);}}$pdo->prepare("UPDATE compras_solicitacoes SET status='RECEBIDA',recebido_em=NOW() WHERE id=? AND status='COMPRADA'")->execute([$id]);$pdo->commit();$msg='Compra recebida e estoque atualizado nos itens vinculados.';}
 }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$err=$e->getMessage();}
}
$os=$pdo->query("SELECT id,numero_os,titulo FROM ordens_servico WHERE status NOT IN ('ENCERRADA','CANCELADA') ORDER BY id DESC LIMIT 300")->fetchAll(PDO::FETCH_ASSOC);$stock=$pdo->query("SELECT id,nome,unidade,custo_unitario FROM estoque_materiais WHERE ativo=1 ORDER BY nome")->fetchAll(PDO::FETCH_ASSOC);$list=$pdo->query("SELECT c.*,u.nome solicitante_nome,os.numero_os,(SELECT GROUP_CONCAT(CONCAT(i.descricao,' x ',i.quantidade) SEPARATOR '; ') FROM compras_itens i WHERE i.compra_id=c.id) itens FROM compras_solicitacoes c LEFT JOIN usuarios u ON u.id=c.solicitante_id LEFT JOIN ordens_servico os ON os.id=c.ordem_servico_id ORDER BY c.id DESC LIMIT 200")->fetchAll(PDO::FETCH_ASSOC);render_header('Compras');
?>
<div class="d-flex justify-content-between align-items-center mb-3"><div><h1 class="h3 mb-1">Compras vinculadas às OS</h1><p class="text-muted mb-0">Solicitação → aprovação → compra → recebimento → estoque.</p></div><a class="btn btn-outline-primary" href="<?=e(app_path('central_aprovacoes'))?>">Central de aprovações</a></div><?php if($msg):?><div class="alert alert-success"><?=e($msg)?></div><?php endif?><?php if($err):?><div class="alert alert-danger"><?=e($err)?></div><?php endif?>
<div class="card mb-3"><div class="card-body"><h2 class="h5">Nova solicitação</h2><form method="post" class="row g-2"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="criar"><div class="col-md-4"><label class="form-label">OS</label><select class="form-select" name="ordem_servico_id"><option value="">Sem vínculo</option><?php foreach($os as $o):?><option value="<?=(int)$o['id']?>"><?=e($o['numero_os'].' — '.$o['titulo'])?></option><?php endforeach?></select></div><div class="col-md-4"><label class="form-label">Item</label><input class="form-control" name="descricao_item" list="stockList" required><datalist id="stockList"><?php foreach($stock as $m):?><option value="<?=e($m['nome'])?>"><?php endforeach?></datalist></div><div class="col-md-2"><label class="form-label">Qtd.</label><input class="form-control" type="number" min="0.01" step="0.01" name="quantidade" value="1" required></div><div class="col-md-2"><label class="form-label">Unidade</label><input class="form-control" name="unidade" value="UND"></div><div class="col-md-3"><label class="form-label">Material do estoque (opcional)</label><select class="form-select" name="material_id"><option value="">Não vincular</option><?php foreach($stock as $m):?><option value="<?=(int)$m['id']?>"><?=e($m['nome'])?></option><?php endforeach?></select></div><div class="col-md-3"><label class="form-label">Custo unitário previsto</label><input class="form-control" type="number" min="0" step="0.01" name="custo_unitario" value="0"></div><div class="col-md-6"><label class="form-label">Justificativa</label><input class="form-control" name="justificativa" placeholder="Por que a compra é necessária?"></div><div class="col-12"><button class="btn btn-primary">Solicitar compra</button></div></form></div></div>
<div class="card"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>#</th><th>OS</th><th>Itens</th><th>Solicitante</th><th>Status</th><th>Valores</th><th>Ações</th></tr></thead><tbody><?php foreach($list as $c):?><tr><td><?=(int)$c['id']?></td><td><?=e($c['numero_os']??'-')?></td><td><?=e($c['itens']??'')?></td><td><?=e($c['solicitante_nome']??'-')?></td><td><span class="badge text-bg-secondary"><?=e($c['status'])?></span></td><td>Prev. R$ <?=e(number_format((float)$c['valor_previsto'],2,',','.'))?><br>Final R$ <?=e(number_format((float)$c['valor_final'],2,',','.'))?></td><td><?php if($canManage&&$c['status']==='APROVADA'):?><form method="post" class="mb-2"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="marcar_comprada"><input type="hidden" name="id" value="<?=(int)$c['id']?>"><input class="form-control form-control-sm mb-1" name="fornecedor" placeholder="Fornecedor"><input class="form-control form-control-sm mb-1" name="documento" placeholder="NF/Documento"><input class="form-control form-control-sm mb-1" type="number" step="0.01" name="valor_final" placeholder="Valor final"><button class="btn btn-sm btn-primary w-100">Marcar comprada</button></form><?php elseif($canManage&&$c['status']==='COMPRADA'):?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="receber"><input type="hidden" name="id" value="<?=(int)$c['id']?>"><button class="btn btn-sm btn-success">Receber / entrar no estoque</button></form><?php else:?><span class="small text-muted">—</span><?php endif?></td></tr><?php endforeach?></tbody></table></div></div>
<?php render_footer(); ?>
